import { CommonModule } from '@angular/common';
import { booleanAttribute, ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, OnInit, Output, SimpleChanges } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { IconComponent } from '../icon/icon.component';
import { ButtonComponent } from '../button/button.component';
import { linkType } from '../../interfaces/common.interface';
import { SecureStorageService } from '../../../core/services/storage/secure-storage.service';
import { toolEvents } from '../../../pdf/interfaces/pdf.interface';
import { MatTooltipModule } from '@angular/material/tooltip';

@Component({
  selector: 'source-card',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [MatCheckboxModule, FormsModule, IconComponent, CommonModule, ButtonComponent, MatTooltipModule],
  templateUrl: './source-card.component.html',
  styleUrl: './source-card.component.scss'
})
export class SourceCardComponent implements OnInit {
  @Input({ transform: booleanAttribute }) launchbtn: boolean = false;
  @Input({ transform: booleanAttribute }) viewsourcebtn: boolean = false;
  @Input({ transform: booleanAttribute }) isveritical: boolean = false;
  @Input({ transform: booleanAttribute }) iconEnd: boolean = false;
  @Input() detail: any;
  @Input() heading: boolean = false;
  @Input() isFactL: boolean = false;
  @Input() hfull: boolean = false;
  @Input() deletebtn: boolean = false;
  @Input() linkbtn: boolean = false;
  @Input() isSelected: boolean = false;
  @Input() deletebtnend: boolean = false;
  @Input() viewbtn: boolean = false;
  @Input() isnavigate: boolean = false;
  @Input() mode: string = '';
  @Input() nUserid: string;
  @Input() addcls: string = '';
  @Input() gap: string = 'M';
  @Input() iconS: string = 'M';
  @Input() type: string = 'F';
  @Input() isCheckbox: boolean = false;
  @Input() truncate: boolean = true;
  @Input() isAllChecked: boolean = true;
  @Input() linktype: linkType | null = null;
  @Output() cardevent = new EventEmitter<any>();
  @Output() onView = new EventEmitter<boolean>();
  @Output() OnEvent = new EventEmitter<toolEvents>();
  @Input() cardheading: string = 'Source File';
  @Input() previewBtn: boolean = false;


  filename: string = '';
  tab: string = '';
  bundle: string = '';
  page: string = '';
  exhibit: string = '';
  jLinktype: linkType = {} as linkType;
  pages: string | null;
  nOwnid: string;

  @Input() compareheading: string = '';

  constructor(private cdr: ChangeDetectorRef, private scureStorage: SecureStorageService) { }

  OnSelect() {
    this.cardevent.emit({ 'type': 'C', data: '' });
  }

  async ngOnInit() {
    this.nOwnid = await this.scureStorage.getUserId();
    this.filename = this.detail.cName || this.detail.cFilename || '';
    this.tab = this.detail.cTab || '−';
    this.bundle = this.detail.cBundletag || '−';
    // this.page = this.detail.cPage || '−';
    this.exhibit = this.detail.cExhibitno || '';
    this.linkData();
    if (this.isnavigate && this.cardheading == '') {
      this.cardheading = 'Current Location'
    }
  }

  linkData() {
    this.jLinktype = this.linktype || this.detail.jLinktype || {} as linkType;
    try {
      if (this.jLinktype?.pages && this.jLinktype?.pages?.length) {
        this.pages = this.jLinktype.pages.join(',');
      }
    } catch (error) {

    }
    this.cdr.detectChanges();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes["linktype"] && !changes["linktype"].firstChange) {
      this.linkData();
    }
    this.cdr.detectChanges();
  }

  deleteThis() {
    this.cardevent.emit({ 'type': 'D' });
  }
  // ViewThis() {
  //   this.cardevent.emit({ 'type': 'V' });
  // }

  ViewThis() {
    this.cardevent.emit({ 'type': 'OPEN-DOC-LINK' });
  }

  view() {
    this.onView.emit(true)
  }




  OnExternalFactSheet() {
    debugger;
    let page = 1
    if (this.detail?.nPage) {
      page = this.detail?.nPage
    } else if (this.detail?.jLinktype?.pages && this.detail?.jLinktype?.pages.length) {
      page = this.detail?.jLinktype?.pages[0]
    } else if (this.detail?.jLinktype?.start) {
      page = this.detail?.jLinktype?.start;
    }
    this.OnEvent.emit({ event: 'EXTERNAL-FACT-SHEET', data: { nFSid: this.detail.nFSid, nBundledetailid: this.detail.nBundledetailid, nPage: page } });
  }


  viewsource() {
    this.OnEvent.emit({ event: 'VIEW-SOURCE', data: this.detail });
  }

  OnSourceCardClick() {
    this.cardevent.emit({ type: 'OPEN-IN-QUICK-VIEW' });
  }
  openPreview() {
    this.cardevent.emit({ 'type': 'OPEN-PREVIEW', data: this.detail });
  }

  openCompareMode() {
    this.cardevent.emit({ event: 'OPEN-COMPARE-MODE', data: { nDocid: this.detail.nDocid, nBundledetailid: this.detail.nBundledetailid } });
  }
}
